window.addEventListener("DOMContentLoaded",(()=>{const t=document.getElementById("phone");window.intlTelInput(t,{initialCountry:"ua",separateDialCode:!0,utilsScript:"https://cdn.jsdelivr.net/npm/intl-tel-input@25.3.1/build/js/utils.js"});!function(){const t=new Date;t.getHours()>=19&&t.setDate(t.getDate()+1);const e=t.toLocaleDateString("uk-UA",{day:"numeric",month:"long"}),n=document.getElementById("day"),o=document.getElementById("when");n&&o&&(n.textContent=`Дата ${e}`,o.textContent=e)}();document.querySelectorAll("[data-scroll]").forEach((t=>{t.addEventListener("click",(function(t){t.preventDefault();const e=this.getAttribute("data-scroll"),n=document.querySelector(e);n&&n.scrollIntoView({behavior:"smooth",block:"start"})}))}))}));